@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_9688787e370f41d1b3105839bfb3b3ca.Models
@using sv_9688787e370f41d1b3105839bfb3b3ca.Services
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav aria-label="Cuisine navigation" class="mb-3">
    <a href="/recipes/1?sort=@Sort" class="btn @(CuisineId == 1 ? "btn-primary" : "btn-outline-primary")">Italian</a>
    <a href="/recipes/2?sort=@Sort" class="btn @(CuisineId == 2 ? "btn-primary" : "btn-outline-primary")">Indian</a>
    <a href="/recipes/3?sort=@Sort" class="btn @(CuisineId == 3 ? "btn-primary" : "btn-outline-primary")">Mexican</a>
</nav>

<div class="mb-3">
    <label class="form-label fw-bold">Sort by:</label>
    <a href="/recipes/@CuisineId?sort=newest" class="btn btn-sm @(Sort == "newest" ? "btn-secondary" : "btn-outline-secondary")">Newest</a>
    <a href="/recipes/@CuisineId?sort=popular" class="btn btn-sm @(Sort == "popular" ? "btn-secondary" : "btn-outline-secondary")">Popular</a>
</div>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _errorMessage is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else if (_recipes is not null)
{
    @if (_isRefreshing)
    {
        <div class="d-flex align-items-center gap-2 mb-3 text-muted">
            <div class="spinner-border spinner-border-sm" role="status"></div>
            <small>Refreshing…</small>
        </div>
    }

    <div class="row row-cols-1 row-cols-md-3 g-4">
        @foreach (var recipe in GetSortedRecipes())
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-muted">
                        <small>Prep time: @recipe.PrepTimeMinutes min</small>
                    </div>
                </div>
            </div>
        }
    </div>

    @if (_recipes.Count == 0)
    {
        <p class="text-muted mt-3">No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;

    protected override async Task OnParametersSetAsync()
    {
        NormalizeSort();

        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            // Only the sort parameter changed — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private void NormalizeSort()
    {
        if (Sort is not ("newest" or "popular"))
        {
            Sort = "newest";
        }
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return new List<Recipe>();

        return Sort == "popular"
            ? _recipes.OrderByDescending(r => r.PrepTimeMinutes).ToList()
            : _recipes.OrderByDescending(r => r.Id).ToList();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        await CancelPendingLoadAsync();

        var cts = new CancellationTokenSource();
        _loadCts = cts;

        _errorMessage = null;
        _isRefreshing = _recipes is not null;

        var cuisineId = CuisineId;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(cuisineId, cts.Token);

            // Only apply if this load wasn't superseded.
            if (!cts.Token.IsCancellationRequested)
            {
                _recipes = result;
                _loadedCuisineId = cuisineId;
                _isRefreshing = false;
            }
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Load was intentionally cancelled — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "The request timed out. Please try again.";
            _isRefreshing = false;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = null;
    }
}

